ry icon-button--size-medium video-dialog__play-button"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="54" height="54" viewBox="0 0 54 54"><path fill="currentColor" d="M22.031 19.687a1 1 0 0 1 1.515-.858l12.188 7.313a1 1 0 0 1 0 1.715L23.546 35.17a1 1 0 0 1-1.515-.857V19.687Z"></path></svg><!--]--></div></div></button><!--teleport start--><!--teleport end--></div></div><div class="hero-content-grid__item hero-content-grid__item--footer"><div class="hero__body u-text-body-large"><!--[--><div><p>Diagnostics + treatment plan + smile design</p>
